using System.Drawing.Printing;
using System.Text;
using MiniPharmacie.Business.Models;
using MiniPharmacie.Business.Services;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.App.Forms;

public sealed class ReportsForm: PharmacyForm
{
    private readonly long actor;private readonly ReportingService reports=new(new DatabaseInitializer());private readonly ComboBox kind=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=190};private readonly DateTimePicker from=new(){Format=DateTimePickerFormat.Short};private readonly DateTimePicker to=new(){Format=DateTimePickerFormat.Short};private readonly DataGridView grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
    private readonly bool manager;
    public ReportsForm(long userId,bool isManager){actor=userId;manager=isManager;Text="Rapports";Width=1100;Height=700;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48,Padding=new Padding(6)};kind.Items.AddRange(manager?["Ventes quotidiennes","Ventes par paiement","Produits les plus vendus","État du stock","Pertes et ajustements"]:["Mes ventes quotidiennes","Mes ventes par paiement","Mes produits vendus"]);kind.SelectedIndex=0;from.Value=DateTime.Today.AddDays(-30);to.Value=DateTime.Today;var load=new Button{Text="Afficher",AutoSize=true};var preview=new Button{Text="Aperçu avant impression",AutoSize=true};var csv=new Button{Text="Exporter CSV",AutoSize=true};var pdf=new Button{Text="Exporter PDF",AutoSize=true};bar.Controls.AddRange([new Label{Text="Rapport",AutoSize=true,Padding=new Padding(0,8,0,0)},kind,new Label{Text="Du",AutoSize=true,Padding=new Padding(0,8,0,0)},from,new Label{Text="au",AutoSize=true,Padding=new Padding(0,8,0,0)},to,load,preview,csv,pdf]);Controls.Add(grid);Controls.Add(bar);Shown+=async(_,_)=>await LoadReport();load.Click+=async(_,_)=>await LoadReport();preview.Click+=(_,_)=>Preview();csv.Click+=(_,_)=>ExportCsv();pdf.Click+=(_,_)=>ExportPdf();}
    private async Task LoadReport(){try{var type=kind.SelectedIndex;IReadOnlyList<ReportEntry> rows=manager?type switch{0=>await reports.GetSalesReportAsync(actor,DateOnly.FromDateTime(from.Value),DateOnly.FromDateTime(to.Value)),1=>await reports.GetSalesReportAsync(actor,DateOnly.FromDateTime(from.Value),DateOnly.FromDateTime(to.Value),true),2=>await reports.GetTopProductsAsync(actor,DateOnly.FromDateTime(from.Value),DateOnly.FromDateTime(to.Value)),3=>await reports.GetStockReportAsync(actor),_=>await reports.GetLossesReportAsync(actor,DateOnly.FromDateTime(from.Value),DateOnly.FromDateTime(to.Value))}:type==2?await reports.GetTopProductsAsync(actor,DateOnly.FromDateTime(from.Value),DateOnly.FromDateTime(to.Value)):await reports.GetSalesReportAsync(actor,DateOnly.FromDateTime(from.Value),DateOnly.FromDateTime(to.Value),type==1);grid.DataSource=rows.Select(x=>new{x.Label,x.Quantity,ChiffreAffaires=x.RevenueMinor,Remboursements=x.RefundMinor,VentesNettes=x.RevenueMinor-x.RefundMinor,CoutHistorique=manager?x.CostMinor:0,MargeBruteIndicative=manager?x.MarginMinor:0}).ToList();if(!manager){grid.Columns["CoutHistorique"]!.Visible=false;grid.Columns["MargeBruteIndicative"]!.Visible=false;}}catch(Exception ex){MessageBox.Show(ex.Message,"Rapport indisponible",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    private void ExportCsv(){using var d=new SaveFileDialog{Filter="Fichier CSV|*.csv",FileName=$"rapport-{DateTime.Now:yyyyMMdd}.csv"};if(d.ShowDialog()!=DialogResult.OK)return;try{var sb=new StringBuilder();sb.AppendLine(string.Join(';',grid.Columns.Cast<DataGridViewColumn>().Where(c=>c.Visible).Select(c=>Csv(c.HeaderText))));foreach(DataGridViewRow row in grid.Rows)if(!row.IsNewRow)sb.AppendLine(string.Join(';',row.Cells.Cast<DataGridViewCell>().Where(c=>c.OwningColumn.Visible).Select(c=>Csv(Convert.ToString(c.Value)??""))));File.WriteAllText(d.FileName,sb.ToString(),new UTF8Encoding(true));MessageBox.Show("Export CSV terminé.");}catch(Exception ex){MessageBox.Show(ex.Message,"Export impossible");}}
    private void ExportPdf(){using var d=new SaveFileDialog{Filter="Document PDF|*.pdf",FileName=$"rapport-{DateTime.Now:yyyyMMdd}.pdf"};if(d.ShowDialog()!=DialogResult.OK)return;try{var lines=new List<string>{$"Rapport : {kind.Text}",$"Période : {from.Value:d} - {to.Value:d}"};lines.Add(string.Join(" | ",grid.Columns.Cast<DataGridViewColumn>().Where(c=>c.Visible).Select(c=>c.HeaderText)));foreach(DataGridViewRow row in grid.Rows)if(!row.IsNewRow)lines.Add(string.Join(" | ",row.Cells.Cast<DataGridViewCell>().Where(c=>c.OwningColumn.Visible).Select(c=>Convert.ToString(c.Value)??"")));SimplePdfExporter.Write(d.FileName,lines);MessageBox.Show("Export PDF terminé.");}catch(Exception ex){MessageBox.Show(ex.Message,"Export impossible");}}
    private void Preview(){var index=0;var lines=grid.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow).Select(r=>string.Join("    ",r.Cells.Cast<DataGridViewCell>().Where(c=>c.OwningColumn.Visible).Select(c=>Convert.ToString(c.Value)))).ToList();var print=new PrintDocument();print.PrintPage+=(_,e)=>{var y=e.MarginBounds.Top;e.Graphics!.DrawString($"Rapport {kind.Text} — {from.Value:d} au {to.Value:d}",Font,Brushes.Black,e.MarginBounds.Left,y);y+=30;while(index<lines.Count&&y<e.MarginBounds.Bottom){e.Graphics.DrawString(lines[index++],Font,Brushes.Black,new RectangleF(e.MarginBounds.Left,y,e.MarginBounds.Width,Font.Height+4));y+=Font.Height+5;}e.HasMorePages=index<lines.Count;};using var dialog=new PrintPreviewDialog{Document=print,Width=1000,Height=700};dialog.ShowDialog(this);}
    private static string Csv(string v){if(v.StartsWith('=')||v.StartsWith('+')||v.StartsWith('-')||v.StartsWith('@'))v="'"+v;return '"'+v.Replace("\"","\"\"")+'"';}
}

internal static class SimplePdfExporter
{
    public static void Write(string path,IReadOnlyList<string> lines){var body=new StringBuilder("BT /F1 9 Tf 40 800 Td 12 TL ");foreach(var line in lines.Take(58)){body.Append('(').Append(Escape(line)).Append(") Tj T* ");}body.Append("ET");var stream=Encoding.Latin1.GetBytes(body.ToString());var objects=new List<byte[]>();objects.Add(Encoding.ASCII.GetBytes("<< /Type /Catalog /Pages 2 0 R >>"));objects.Add(Encoding.ASCII.GetBytes("<< /Type /Pages /Kids [3 0 R] /Count 1 >>"));objects.Add(Encoding.ASCII.GetBytes("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>"));objects.Add(Encoding.ASCII.GetBytes("<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>"));using var streamObj=new MemoryStream();var prefix=Encoding.ASCII.GetBytes($"<< /Length {stream.Length} >>\nstream\n");streamObj.Write(prefix);streamObj.Write(stream);streamObj.Write(Encoding.ASCII.GetBytes("\nendstream"));objects.Add(streamObj.ToArray());using var output=new MemoryStream();void W(string s){var b=Encoding.ASCII.GetBytes(s);output.Write(b);}W("%PDF-1.4\n");var offsets=new List<long>{0};for(var i=0;i<objects.Count;i++){offsets.Add(output.Position);W($"{i+1} 0 obj\n");output.Write(objects[i]);W("\nendobj\n");}var xref=output.Position;W($"xref\n0 {objects.Count+1}\n0000000000 65535 f \n");foreach(var offset in offsets.Skip(1))W($"{offset:0000000000} 00000 n \n");W($"trailer << /Size {objects.Count+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF");File.WriteAllBytes(path,output.ToArray());}
    private static string Escape(string s)=>s.Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)").Replace("\r"," ").Replace("\n"," ");
}
